// Connexion directe PostgreSQL via 10.14.219.2:5433
const { Client } = require('pg');
const client = new Client({
  host    : '10.14.219.2',
  port    : 5433,
  database: 'database_extern_local',
  user    : 'postgres',
  password: 'postgres',
  connectionTimeoutMillis: 10000,
  statement_timeout      : 30000
});
await client.connect();
const res = await client.query('SELECT row_to_json(t) AS r FROM \"clients\" t');
await client.end();
const rows = res.rows.map(row => row.r);
const payload = JSON.stringify({ data: rows });
const buf = Buffer.from(payload, 'utf8');
console.log('[WF-03] PG clients : ' + rows.length + ' lignes');
return [{
  json: { table: 'clients', rowCount: rows.length, key: 'raw/database/clients/latest/clients.json' },
  binary: { tableData: { data: buf.toString('base64'), mimeType: 'application/json', fileName: 'clients.json' } }
}];

const fs = require('fs');
// Lire le binaire depuis le noeud PG (S3 consomme le binary en sortie)
const pgItem = $('Requête PG — clients').first();
const buf = Buffer.from(pgItem.binary.tableData.data, 'base64');
fs.mkdirSync('/staging/database', { recursive: true });
fs.writeFileSync('/staging/database/clients.json', buf);
const rows = $input.first().json.rowCount ?? pgItem.json.rowCount;
console.log('[WF-03] ✅ clients stagé : ' + rows + ' lignes');
return [{ json: { status: 'success', table: 'clients', rows } }];

